    "title": "The Umbrella Basket",
    "passage": "Every morning, Ms. Lin puts a blue basket near the front door of her coffee shop. The basket is not for flowers or newspapers. It is for umbrellas.\n\nThe idea started on a rainy day three years ago. A student ran into the shop without an umbrella. He was wet from head to toe and looked worried because he still had to walk to school. Ms. Lin gave him an old umbrella and told him to bring it back when he could.\n\nThe next day, the student returned the umbrella with another one. \"This is from my house,\" he said. \"Maybe someone else will need it.\"\n\nSince then, the basket has never been empty. People take an umbrella when they need one and leave one when they can. Ms. Lin says the basket does not make her shop richer, but it makes the street warmer.",
