    "category": "set-01",
    "title": "The Quiet Bell",
    "passage": "Our school bell used to be very loud. It rang between classes, before lunch, after lunch, and at the end of the day. Most students never thought about it, but Eric did.\n\nEric was new to our class. He was good at math and drawing, but he always covered his ears when the bell rang. At first, some students laughed. Then our teacher told us that loud sounds made Eric feel pain.\n\nOne week later, the school tried a new bell. It played a short piece of music instead of a sharp ringing sound. The music was still clear enough for everyone to hear, but it was much softer.\n\nNo one expected the change to matter much. However, teachers found that students walked more calmly between classes. Eric no longer covered his ears. Sometimes a small change helps more people than we first think.",
