    "passage": "Leo found an old bike behind his grandfather's house. It was red, but most of the paint was gone. One tire was flat, and the seat was broken.\n\n\"Can I throw it away\" Leo asked.\n\nHis grandfather shook his head. \"That bike carried me to my first job.\"\n\nLeo looked at the bike again. It was hard to believe that something so old had once been important. That weekend, he cleaned it, changed the tires, and bought a new seat with his pocket money. His grandfather helped him fix the chain.\n\nWhen the bike was ready, Leo rode it slowly down the street. It made a little noise, but it worked.\n\nHis grandfather smiled from the gate. \"Now it has carried two people into a new part of life,\" he said.\n\nLeo did not fully understand the sentence, but he knew the bike would not be left behind the tree again.",
