    "passage": "Mr. Brown teaches English in a small mountain school. Every Monday morning, he asks his students one question: \"What made you smile last week\"\n\nAt first, the students thought the question was strange. Some said they could not remember anything. Others gave very short answers, like \"food\" or \"sleep.\"\n\nAfter a few weeks, their answers became longer. One student said his little sister learned to tie her shoes. Another said his father came home early and cooked dinner. A quiet girl said she smiled when a bus driver waited for her in the rain.\n\nMr. Brown writes some of the answers on colored paper and puts them on the classroom wall. The wall is now full of small happy moments.\n\nHe says the activity is not only for speaking practice. It also teaches students to notice good things before they disappear from memory.",
