    "category": "set-01",
    "title": "The Repair Table",
    "passage": "Every second Sunday, people in Pine Town bring broken things to the community center. Lamps, toys, clocks, chairs, and bags are placed on a long wooden table. Volunteers sit behind the table with tools.\n\nThe event is called Repair Morning. It was started by a group of retired workers. They wanted people to stop throwing away things that could still be fixed.\n\nNot everything can be saved. Some parts are too old, and some machines are too dangerous to repair. But many things get a second life. A boy once brought a toy train that had not moved for two years. After twenty minutes, it ran around the table again.\n\nRepair Morning is not a store, so people do not pay. Instead, they are asked to learn. The volunteers explain what they are doing, because the real goal is not only to fix objects. It is to fix the habit of giving up too soon.",
