    "passage": "Class 809 had a plant named Lucky. No one knew who brought it to the classroom. It simply appeared by the window one Monday morning.\n\nAt first, students forgot about it. Its leaves became dry, and the soil was hard. Then Mina put a small note beside it: \"I am thirsty.\"\n\nEveryone laughed, but someone watered it. The next day, another note appeared: \"Thank you. I like sunlight too.\" Soon, the class made a watering list.\n\nLucky slowly became healthier. Students started talking to it before tests. Some asked it for good luck. Others touched its leaves after they finished cleaning the classroom.\n\nAt the end of the semester, the teacher said Lucky had taught the class an important lesson. Living things do not always ask loudly for help. Sometimes they only wait quietly for someone to notice.",
