    "category": "set-02",
    "title": "Grandpa's Password",
    "passage": "Grandpa Lin bought his first smartphone last month. His family helped him set a password, but he forgot it the next day. They changed it to his birthday. He forgot that too.\n\n\"Maybe phones are not for me,\" he said.\n\nHis granddaughter Amy had another idea. She asked him what number he would never forget. Grandpa thought for a long time and said, \"The number of the bus I took to meet your grandmother.\"\n\nAmy used that number as the password. Grandpa remembered it easily.\n\nSoon he learned to send messages. His first message to Amy was full of mistakes, but she understood it: \"I am learning slowly. Do not laugh too much.\"\n\nAmy did laugh, but she also saved the message. To her, it was better than a perfect sentence. It showed that Grandpa was willing to enter a new world, one number at a time.",
