    "passage": "During art class, the teacher showed students how to fold paper cranes. Most students finished quickly, but Alan could not make the wings right.\n\nHe became angry and crushed his paper. The teacher gave him another sheet and said, \"Slow hands can still learn.\"\n\nAlan tried again. His second crane looked worse than the first. His third one stood, but one wing was too short. By the fifth try, it finally looked like a crane.\n\nAlan placed it on his desk and felt proud. It was not the best crane in class, but it was the one that taught him the most.\n\nHe took it home carefully. To others, it was only folded paper. To Alan, it was proof that trying again can change the shape of failure.",
