    "passage": "The school talent show began at seven o'clock. The first performer was supposed to play the violin, but she was not there. The stage stayed empty.\n\nThe host became nervous. The audience started talking.\n\nThen a teacher walked on stage and asked everyone to be patient. She told a funny story about her first performance as a child. People laughed, and the room became calmer.\n\nFive minutes later, the violin player arrived. She had been stuck in traffic and looked close to tears. The audience clapped before she even began.\n\nHer music was not perfect, but people listened warmly.\n\nThe empty stage could have become an embarrassment. Instead, because someone filled the silence with kindness, it became part of the show.",
