    "passage": "Mark bought a snow globe at a second-hand shop. Inside it was a tiny house, a tree, and a small dog. When he shook it, white snow moved around slowly.\n\nHis sister asked why he wanted an old toy.\n\nMark said it reminded him of his childhood. He used to visit his grandmother in the mountains, where snow covered everything in winter.\n\nHe placed the snow globe on his desk. When homework made him tired, he shook it and watched the snow fall.\n\nNothing inside the globe changed. The house stayed still, and the dog never moved. But for Mark, that was the point. Some small objects help people rest because they hold a quiet world that does not hurry.",
