    "passage": "Daniel's grandfather gave him an old camera. It used film, not memory cards. Daniel could not see the photos right after taking them.\n\nAt first, he found this annoying. With his phone, he could take many pictures and delete the bad ones. With the old camera, every photo cost money.\n\nBecause of this, Daniel became more careful. He looked at light, waited for people to stop moving, and thought before pressing the button.\n\nWhen the photos were finally printed, not all of them were good. But the good ones felt special.\n\nDaniel still used his phone often, but the old camera taught him a different way to look. Not everything needs to be quick to be useful.",
