    "category": "set-13",
    "title": "The Last Page",
    "passage": "Emma loved reading novels, but she had a bad habit. She always read the last page first.\n\nHer brother said this ruined the story. Emma disagreed. She liked knowing how things ended because it made her feel safe.\n\nOne day, she borrowed a mystery book from the library. The last page was missing. Emma was annoyed, but she began reading anyway.\n\nWithout knowing the ending, she paid more attention to clues. She guessed, changed her mind, and felt surprised by each chapter.\n\nWhen she reached the missing page, she went to the library and found another copy. The ending was better because she had waited.\n\nEmma did not stop reading last pages forever, but she understood why some journeys need uncertainty.",
