    "category": "set-14",
    "title": "The Late Birthday Card",
    "passage": "Sophie forgot her friend's birthday. She remembered two days later and felt terrible.\n\nShe thought about pretending she had sent a message, but the phone had failed. Instead, she bought a card and wrote the truth: \"I forgot. I am sorry. You are important to me even when my memory is not good.\"\n\nHer friend laughed when she read it. \"This is the most honest birthday card I have ever received,\" she said.\n\nSophie was relieved.\n\nBeing late was not good, but lying would have been worse. The card taught Sophie that an apology does not need to be perfect. It needs to be clear, honest, and followed by better care next time.",
