    "category": "set-15",
    "title": "The Tea Lesson",
    "passage": "Mina's grandfather made tea slowly. He warmed the cup, smelled the leaves, waited for the water to cool a little, and poured carefully.\n\nMina thought it took too long. She preferred bottled tea from a store.\n\nOne afternoon, her grandfather asked her to make tea with him. He explained that hot water could make some tea bitter. Waiting changed the taste.\n\nMina tried the tea. It was softer than bottled tea, but she liked it.\n\nHer grandfather said, \"Fast is useful. Slow has its own flavor.\"\n\nMina still bought bottled tea sometimes, but she no longer thought slow tea was only for old people. It was a lesson in patience that could be tasted.",
