    "passage": "There was an old bowl in Mia's kitchen. It had a crack on one side, so no one used it for soup anymore.\n\nMia's mother filled it with soil and planted green onions inside. The bowl sat by the window, and new leaves grew from it.\n\nMia asked why they did not just throw it away.\n\nHer mother said, \"It cannot do its old job, but it can still do a new one.\"\n\nWeeks later, Mia cut green onions from the bowl for dinner. She looked at the crack and thought it made the bowl more interesting.\n\nThe old bowl taught her that broken things are not always finished. Sometimes they only need a different purpose.",
